@pytest.fixture(scope="module")
def game():
    return run_simulation()


def test_snake_never_dies(game):
    assert game.alive, f"snake died at tick {game.tick}"
    assert game.tick == TICKS


def test_snake_eats_enough_food(game):
    assert game.score >= 15, f"only ate {game.score} food"


def test_safety_check_rejects_at_least_one_greedy_move(game):
    assert game.rejected_greedy_moves > 0, (
        "safety check never vetoed a greedy move"
    )


def test_run_is_deterministic(game):
    assert state_hash(game) == EXPECTED_HASH, (
        f"final state changed!\n got: {state_hash(game)}\n exp: {EXPECTED_HASH}"
    )
